require_once __DIR__.'/../includes/auth.php';auth_require();require_once __DIR__.'/../includes/listing.php';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 $id=(int)($_POST['customer_id']??0);domain_require('customers.'.($id?'edit':'create'));$type=$_POST['relationship_type']??'';$trade=$_POST['trade_type']??'';
 if(!in_array($type,['walk_in','registered','regular'],true)||!in_array($trade,['retail','wholesale'],true))throw new InvalidArgumentException('Invalid customer category.');
 $name=trim((string)($_POST['name']??''));if($name===''||mb_strlen($name)>100)throw new InvalidArgumentException(__t('Enter a name up to 100 characters.','نام مشتری را تا ۱۰۰ حرف بنویسید.','نوم تر ۱۰۰ تورو ولیکئ.'));
