 $old=null;if($id){$q=$pdo->prepare('SELECT * FROM customers WHERE id=? AND shop_id=?');$q->execute([$id,shop_id()]);$old=$q->fetch();if(!$old)throw new RuntimeException('Customer unavailable.',403);$pdo->prepare('UPDATE customers SET name=?,phone=?,company=?,address=?,notes=?,relationship_type=?,trade_type=? WHERE id=? AND shop_id=?')->execute([$name,$phone,$company,$address,$notes,$type,$trade,$id,shop_id()]);}
 else{$pdo->prepare('INSERT INTO customers (name,phone,company,address,notes,relationship_type,trade_type,shop_id) VALUES (?,?,?,?,?,?,?,?)')->execute([$name,$phone,$company,$address,$notes,$type,$trade,shop_id()]);$id=(int)$pdo->lastInsertId();}
 domain_audit($old?'customer_edited':'customer_created','customer',$id,['name'=>$name,'relationship_type'=>$type,'trade_type'=>$trade],null,$old);redirect(BASE_URL.'modules/customers.php');
