$tradeFilter=is_string($_GET['trade']??null)?$_GET['trade']:'';$type=$_GET['relationship']??'';$search=trim((string)($_GET['q']??''));$args=[shop_id()];$where='shop_id=?';if(in_array($type,['walk_in','registered','regular'],true)){$where.=' AND relationship_type=?';$args[]=$type;}if($search!==''){$where.=' AND (name LIKE ? OR phone LIKE ?)';$args[]='%'.mb_substr($search,0,100).'%';$args[]='%'.mb_substr($search,0,100).'%';}
if(in_array($tradeFilter,['retail','wholesale'],true)){$where.=' AND trade_type=?';$args[]=$tradeFilter;}
$sorts=['name_asc'=>['name ASC,id ASC','Name: A–Z','نام: الف تا ی'],'name_desc'=>['name DESC,id DESC','Name: Z–A','نام: ی تا الف'],'newest'=>['id DESC','Newest first','تازه‌ترین اول'],'oldest'=>['id ASC','Oldest first','قدیمی‌ترین اول']];$list=listing_state($sorts,'name_asc');$count=$pdo->prepare('SELECT COUNT(*) FROM customers WHERE '.$where);$count->execute($args);$list=listing_count($list,(int)$count->fetchColumn());
$q=$pdo->prepare('SELECT * FROM customers WHERE '.$where.' ORDER BY '.$list['order'].' LIMIT '.$list['size'].' OFFSET '.$list['offset']);$q->execute($args);$rows=$q->fetchAll();$editing=null;
if(isset($_GET['edit'])){domain_require('customers.edit');$q=$pdo->prepare('SELECT * FROM customers WHERE id=? AND shop_id=?');$q->execute([(int)$_GET['edit'],shop_id()]);$editing=$q->fetch();if(!$editing)access_deny(404,'not_found','Customer not found.');}
$types=['walk_in'=>__t('Walk-in','گذری','یو ځل پېرودونکی'),'registered'=>__t('Registered','ثبت‌شده','ثبت شوی'),'regular'=>__t('Regular','همیشگی','دایمي')];$trades=['retail'=>__t('Retail','پرچون','پرچون'),'wholesale'=>__t('Wholesale','عمده','عمده')];
