<h2><?= sanitize($pageTitle) ?></h2><?php if($error):?><p role="alert"><?= sanitize($error) ?></p><?php endif ?>
<form method="get" class="card form-grid"><label><?= __t('Search name or phone','جستجوی نام یا شماره','نوم یا شمېره ولټوئ') ?><input class="form-control" name="q" value="<?= sanitize($search) ?>"></label><details class="list-advanced"><summary><?= __t('Filters & order','انتخاب و ترتیب لست','د لست فلټر او ترتیب') ?></summary><div class="form-grid"><label><?= __t('Relationship','رابطه با تجارت','له سوداګرۍ سره اړیکه') ?><select class="form-control" name="relationship"><option value=""><?= __t('All','همه','ټول') ?></option><?php foreach($types as $k=>$label):?><option value="<?= $k ?>" <?= $k===$type?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label><?= __t('Trade type','نوع خرید','د پېرود ډول') ?><select class="form-control" name="trade"><option value=""><?= __t('All','همه','ټول') ?></option><?php foreach($trades as $k=>$label):?><option value="<?= $k ?>" <?= $k===$tradeFilter?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><?php listing_fields($list) ?></div></details><button class="btn btn-primary"><?= __t('Search','جستجو','لټون') ?></button></form>
