<div class="card modern-form table-responsive"><table class="table"><thead><tr><?php foreach([__t('Name','نام','نوم'),__t('Phone','شماره','شمېره'),__t('Relationship','رابطه','اړیکه'),__t('Trade type','نوع خرید','د پېرود ډول'),__t('Action','عملیات','عمل')] as $h):?><th><?= $h ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= sanitize($r['name']) ?></td><td><?= sanitize($r['phone']) ?></td><td><?= $types[$r['relationship_type']]??$types['registered'] ?></td><td><?= $trades[$r['trade_type']]??$trades['retail'] ?></td><td><?php if(domain_can('customers.edit')):?><a href="?edit=<?= (int)$r['id'] ?>"><?= __t('Edit','ویرایش','بدلول') ?></a><?php endif ?></td></tr><?php endforeach ?></tbody></table></div>
